<body>
  <main class="support-shell">
    <h1>Contact support</h1>
    <p class="intro">Tell us how we can help and a support specialist will get back to you shortly.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Jordan Lee" required>
        <p class="error-message" id="full-name-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input id="email-address" name="email" type="email" autocomplete="email" placeholder="jordan@example.com" required>
        <p class="error-message" id="email-address-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phone" type="tel" autocomplete="tel" placeholder="(555) 123-4567" aria-describedby="phone-helper phone-number-error">
        <p class="helper-text" id="phone-helper">Optional. Use a format like (555) 123-4567 or +1 555 123 4567.</p>
        <p class="error-message" id="phone-number-error" aria-live="polite"></p>
      </div>

      <button class="submit-button" type="submit">Send message</button>
      <p class="form-status" id="form-status" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");

    const fields = {
      fullName: {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }
          return "";
        }
      },
      email: {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Enter a valid email address.";
          }
          return "";
        }
      },
      phone: {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        validate(value) {
          if (!value.trim()) {
            return "";
          }
          const phonePattern = /^[+]?[0-9()\-\s]{7,20}$/;
          if (!phonePattern.test(value.trim())) {
            return "Use digits, spaces, parentheses, or hyphens only.";
          }
          return "";
        }
      }
    };

    function setFieldError(fieldConfig, message) {
      const wrapper = fieldConfig.input.closest(".form-field");
      fieldConfig.error.textContent = message;
      fieldConfig.input.setAttribute("aria-invalid", message ? "true" : "false");
      wrapper.classList.toggle("has-error", Boolean(message));
    }

    function validateField(fieldConfig) {
      const message = fieldConfig.validate(fieldConfig.input.value);
      setFieldError(fieldConfig, message);
      return !message;
    }

    Object.values(fields).forEach((fieldConfig) => {
      fieldConfig.input.addEventListener("blur", () => {
        validateField(fieldConfig);
      });

      fieldConfig.input.addEventListener("input", () => {
        if (fieldConfig.error.textContent) {
          validateField(fieldConfig);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      statusMessage.textContent = "";
      statusMessage.classList.remove("is-success");

      const isValid = Object.values(fields).every((fieldConfig) => validateField(fieldConfig));

      if (!isValid) {
        return;
      }

      statusMessage.textContent = "Thanks. Your support request has been sent.";
      statusMessage.classList.add("is-success");
      form.reset();

      Object.values(fields).forEach((fieldConfig) => {
        setFieldError(fieldConfig, "");
        fieldConfig.input.setAttribute("aria-invalid", "false");
      });
    });
  </script>
</body>
</html>
